'use strict';
document.addEventListener('click', async event => {
  const button = event.target.closest('button');
  if (!button) return;
  if (button.dataset.go) {
    // Only same-origin paths generated by this site are used for navigation.
    const target = new URL(button.dataset.go, window.location.origin);
    if (target.origin === window.location.origin) window.location.assign(target.pathname + target.search);
    return;
  }
  if (button.id === 'open-message') {
    const picker = document.getElementById('message-picker');
    if (picker) window.location.assign(picker.value);
    return;
  }
  if (button.dataset.copy) {
    const node = document.getElementById(button.dataset.copy);
    const status = document.getElementById('ed-status');
    if (!node) return;
    try {
      await navigator.clipboard.writeText('value' in node ? node.value : node.textContent);
      const label = button.textContent;
      button.textContent = 'Copied';
      if (status) status.textContent = 'Copied. Use a dedicated QA application for this test.';
      window.setTimeout(() => { button.textContent = label; }, 1600);
    } catch {
      if ('select' in node) node.select();
      else { const range = document.createRange(); range.selectNodeContents(node); const selection = window.getSelection(); selection.removeAllRanges(); selection.addRange(range); }
      if (status) status.textContent = 'Clipboard unavailable. The value is selected; copy it manually.';
    }
  }
});

// Progressive enhancement: all case cards remain available when JavaScript is disabled.
function applyCaseFilters() {
  const input = document.getElementById('case-search');
  const select = document.getElementById('category-filter');
  if (!input || !select) return;
  const query = input.value.trim().toLocaleLowerCase();
  const cards = [...document.querySelectorAll('[data-case-card]')];
  let visible = 0;
  for (const card of cards) {
    const match = (!select.value || card.dataset.category === select.value) && (!query || card.dataset.search.includes(query));
    card.hidden = !match;
    if (match) visible++;
  }
  document.getElementById('case-count').textContent = `${visible} of ${cards.length} crawler cases`;
  document.getElementById('no-cases').hidden = visible !== 0;
}
document.getElementById('case-search')?.addEventListener('input', applyCaseFilters);
document.getElementById('category-filter')?.addEventListener('change', applyCaseFilters);
document.getElementById('clear-filters')?.addEventListener('click', () => {
  document.getElementById('case-search').value = '';
  document.getElementById('category-filter').value = '';
  applyCaseFilters();
  document.getElementById('case-search').focus();
});
document.getElementById('open-workflow')?.addEventListener('click', () => {
  const target = document.getElementById('workflow-picker');
  if (target) window.location.assign(target.value);
});
